"""An LRU cache with per-entry time-to-live (TTL).

Standard library only. Time is injected through a zero-argument callable
(``now``) so tests can control it; it defaults to :func:`time.monotonic`.

An entry is EXPIRED when ``now() - (time it was last written) >= ttl_seconds``.
Expired entries are transparent: they are removed when encountered, are never
counted by :meth:`Cache.__len__` or :meth:`Cache.keys`, and never occupy
capacity -- a :meth:`Cache.put` that needs room drops every expired entry
before evicting a live one.
"""

import time
from collections import OrderedDict


class Cache:
    """A bounded LRU cache in which each entry expires ``ttl_seconds`` after
    it was last written.

    Ordering invariant: the internal mapping is kept ordered
    least-recently-used first, most-recently-used last.
    """

    def __init__(self, capacity, ttl_seconds, now=time.monotonic):
        if capacity < 0:
            raise ValueError("capacity must be >= 0")
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must be >= 0")
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self._now = now
        # key -> (value, written_at); ordered least-recently-used first.
        self._data = OrderedDict()

    # -- internal helpers ---------------------------------------------------

    def _is_expired(self, written_at):
        return self._now() - written_at >= self.ttl_seconds

    def _purge_expired(self):
        """Remove every expired entry. Returns the number removed."""
        expired = [
            key
            for key, (_, written_at) in self._data.items()
            if self._is_expired(written_at)
        ]
        for key in expired:
            del self._data[key]
        return len(expired)

    def _make_room(self):
        """Ensure there is room for one more entry.

        First drops every expired entry; only if the cache is still full
        does it evict the least-recently-used LIVE entry.
        """
        while len(self._data) >= self.capacity:
            if self._purge_expired():
                continue
            if not self._data:
                break
            self._data.popitem(last=False)

    # -- public API -----------------------------------------------------------

    def put(self, key, value):
        """Insert ``key`` or update it.

        Either way the entry becomes the most-recently-used and its TTL
        clock resets (an update makes it fresh again).
        """
        if key in self._data:
            del self._data[key]
        else:
            self._make_room()
        # New keys are appended at the end (most-recently-used).
        self._data[key] = (value, self._now())

    def get(self, key):
        """Return the value, or ``None`` if the key is absent or expired.

        A get that finds an EXPIRED entry removes it and does NOT change
        recency ordering -- it is not a use. A get that returns a live value
        makes that entry the most-recently-used.
        """
        entry = self._data.get(key)
        if entry is None:
            return None
        value, written_at = entry
        if self._is_expired(written_at):
            del self._data[key]
            return None
        self._data.move_to_end(key)
        return value

    def __len__(self):
        """Number of LIVE entries (expired ones are dropped first)."""
        self._purge_expired()
        return len(self._data)

    def keys(self):
        """Live keys, least-recently-used first."""
        self._purge_expired()
        return list(self._data.keys())

    def __contains__(self, key):
        entry = self._data.get(key)
        return entry is not None and not self._is_expired(entry[1])
